    {
      "id": "dc590288-1d4a-4411-8c3d-07b4bf0697bc",
      "question": "What power is required?",
      "answer": "One standard 120V household outlet.",
      "page": "rental",
      "sort_order": 6
    },
    {
      "id": "dd4d4c9e-5a1f-44c3-8c23-29b4b6ff6367",
      "question": "Can decorations or balloons be added to a party?",
      "answer": "Yes. Balloon decorations can be added to themed party décor to enhance your celebration.",
      "page": "birthdays",
      "sort_order": 32
    },
    {
      "id": "de59ddcc-4121-43e0-a8ac-29659ce0d5fa",
      "question": "How much space is needed?",
      "answer": "Most machines require about 3 feet by 3 feet of dry (under-roof) space with a solid floor.",
      "page": "rental",
      "sort_order": 5
    },
    {
      "id": "e3f43061-2693-4320-a50e-6ad8b55149e7",
      "question": "Does Klawsome offer anything special for birthdays without booking a party?",
      "answer": "Yes. Guests can visit anytime during regular hours and receive a personalized birthday gift bag and balloon for the celebrant. No purchase is necessary — just subscribe to Klawsome's newsletter to redeem.",
      "page": "birthdays",
      "sort_order": 33
    },
    {
      "id": "e97e580f-4e77-4ace-b1cf-98132d198ff4",
      "question": "Can the machine be set to \"always win\"?",
      "answer": "Yes — we offer a free-play / easy-win mode so every guest leaves with a prize. Just let us know the difficulty level you'd like when booking.",
      "page": "rental",
      "sort_order": 103
    },
    {
      "id": "ea78e3b2-8434-4f95-ac37-1e08df58d988",
      "question": "How far in advance should I book?",
      "answer": "We need at least 10 days to book ahead.",
      "page": "rental",
      "sort_order": 7
    },
    {
      "id": "f235fde5-6451-4e60-b5d5-a8fce76704cc",
      "question": "Do you offer parties or party packages?",
      "answer": "Yes! Please visit our Birthdays page for more details on private and semi-private party options.",
      "page": "miscellaneous",
      "sort_order": 14
    },
    {
      "id": "f3f16bc3-3178-491d-968a-6293e114d424",
      "question": "What are my upgrade options?",
      "answer": "We have a full wall at the redemption counter of other larger and more rare prizes. There is a points system that a friendly associate can explain.",
      "page": "plushies",
      "sort_order": 7
    },
    {
      "id": "f71c11b6-5f43-4059-9ddc-4b5d4db23d84",
      "question": "Can I bring my own food, cake, and drinks?",
      "answer": "Yes! Klawsome does not provide food/beverages, so feel free to bring any food, cake, beverages, etc. However, please note that for a semi-private party with Paris Baguette, outside food is not permitted. Purchase of food from Paris Baguette is required.",
      "page": "birthdays",
      "sort_order": 31
    },
    {
      "id": "f8f22d98-cc90-433b-afbe-db74ab012b0f",
      "question": "What if my question isn't answered here?",
      "answer": "Feel free to contact us using our submission form, or drop by and talk with us directly! We can't wait to welcome you to our Klawsome community!",
      "page": "miscellaneous",
      "sort_order": 17
    }
